export interface ConnectorConfig {
  /** Full Discord webhook URL (e.g., https://discord.com/api/webhooks/123/abc) */
  discordWebhookUrl: string
  /** Optional fetch implementation for testing */
  fetch?: typeof fetch
}

export interface AirtableWebhookPayload {
  id: string
  fields: Record<string, unknown>
}

export interface DiscordMessageResponse {
  id: string
  channel_id: string
  content: string
  timestamp: string
}

export interface HandleResult {
  messageId: string
  channelId: string
}

function formatContent(payload: AirtableWebhookPayload): string {
  const fieldEntries = Object.entries(payload.fields)
  const fieldString = fieldEntries
    .map(([key, value]) => `${key}: ${String(value)}`)
    .join(', ')
  return `New Airtable row: ${payload.id} - ${fieldString}`
}

export async function handle(
  payload: AirtableWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  if (!payload.id) {
    throw new Error('Missing required field: id')
  }
  if (!payload.fields || typeof payload.fields !== 'object') {
    throw new Error('Missing required field: fields')
  }
  if (!config.discordWebhookUrl) {
    throw new Error('Missing required config: discordWebhookUrl')
  }

  const content = formatContent(payload)
  if (content.length > 2000) {
    throw new Error('Formatted message content exceeds Discord 2000 character limit')
  }

  const fetchImpl = config.fetch ?? fetch
  const response = await fetchImpl(config.discordWebhookUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ content }),
  })

  if (!response.ok) {
    throw new Error(
      `Discord webhook request failed with status ${response.status} at ${config.discordWebhookUrl}`
    )
  }

  const data = (await response.json()) as DiscordMessageResponse
  return {
    messageId: data.id,
    channelId: data.channel_id,
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, AirtableWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      discordWebhookUrl: 'https://discord.com/api/webhooks/123456/abcdef',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as AirtableWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.messageId).toBe('123456789012345678')
    expect(result.channelId).toBe('987654321098765432')
  })
})

describe('handle', () => {
  it('sends formatted message to Discord webhook on happy path', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) =>
      jsonResponse(
        {
          id: 'msg-123',
          channel_id: 'chan-456',
          content: 'New Airtable row: rec123abc456def - Name: John Doe, Email: john@example.com',
          timestamp: '2024-01-01T12:00:00.000Z',
        },
        200
      )
    )

    const payload: AirtableWebhookPayload = {
      id: 'rec123abc456def',
      fields: { Name: 'John Doe', Email: 'john@example.com' },
    }
    const config: ConnectorConfig = {
      discordWebhookUrl: 'https://discord.com/api/webhooks/123/token',
      fetch,
    }

    const result = await handle(payload, config)

    expect(result.messageId).toBe('msg-123')
    expect(result.channelId).toBe('chan-456')
    expect(calls).toHaveLength(1)
    expect(calls[0].method).toBe('POST')
    expect(calls[0].url).toBe('https://discord.com/api/webhooks/123/token')
    expect(calls[0].json).toEqual({
      content: 'New Airtable row: rec123abc456def - Name: John Doe, Email: john@example.com',
    })
  })

  it('throws when payload.id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { fields: { Name: 'Test' } } as unknown as AirtableWebhookPayload
    const config: ConnectorConfig = { discordWebhookUrl: 'https://discord.com/api/webhooks/1/2', fetch }

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: id')
  })

  it('throws when payload.fields is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { id: 'rec123' } as unknown as AirtableWebhookPayload
    const config: ConnectorConfig = { discordWebhookUrl: 'https://discord.com/api/webhooks/1/2', fetch }

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: fields')
  })

  it('throws when config.discordWebhookUrl is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload: AirtableWebhookPayload = { id: 'rec123', fields: { Name: 'Test' } }
    const config = { fetch } as ConnectorConfig

    await expect(handle(payload, config)).rejects.toThrow('Missing required config: discordWebhookUrl')
  })

  it('throws on non-2xx response from Discord', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ message: 'Unauthorized' }, 401))
    const payload: AirtableWebhookPayload = { id: 'rec123', fields: { Name: 'Test' } }
    const config: ConnectorConfig = {
      discordWebhookUrl: 'https://discord.com/api/webhooks/123/token',
      fetch,
    }

    await expect(handle(payload, config)).rejects.toThrow(
      'Discord webhook request failed with status 401 at https://discord.com/api/webhooks/123/token'
    )
    expect(calls).toHaveLength(1)
  })

  it('throws when formatted content exceeds 2000 characters', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const longFieldValue = 'x'.repeat(2000)
    const payload: AirtableWebhookPayload = {
      id: 'rec123',
      fields: { Description: longFieldValue },
    }
    const config: ConnectorConfig = {
      discordWebhookUrl: 'https://discord.com/api/webhooks/123/token',
      fetch,
    }

    await expect(handle(payload, config)).rejects.toThrow('exceeds Discord 2000 character limit')
  })
})

